const lv_image_dsc_t *product_ui_icon_get_sized(product_ui_icon_id_t icon_id, uint16_t size)
{
    if (icon_id < 0 || icon_id >= PRODUCT_UI_ICON_COUNT) return NULL;
    switch (size) {
    case 12: return s_icons_12[icon_id];
    case 14: return s_icons_14[icon_id];
    case 16: return s_icons_16[icon_id];
    case 18: return s_icons_18[icon_id];
    default: return NULL;
    }
}
